@startuml

class Resident {
  + name : string
  + streetAddress : string
  + phoneNumber : string
  + email : string
}

class PickupRequest {
  + streetAddress : string
  + description : string
  + pickupTime : time
}

class Article {
  + description : string
  + dimensions : string
  + weight : float
  + category : string
}

class Vehicle {
  + storageSpace : float
}

class Route {
  + day : date
}

class VolunteerDriver {
  + availableDays : string[]
}

class H2SLocation {
}

class DistributionCenter extends H2SLocation {}

class FoodBank {
}

class Client {
  + homeAddress : string
  + neededCategories : string[]
}

class Delivery {
}

H2SLocation "1" -- "*" PickupRequest : manages
Resident "1" -- "*" PickupRequest : makes
PickupRequest "1" -- "*" Article : contains
Vehicle "1" -- "*" Route : follows
VolunteerDriver "1" -- "*" Route : drives
Route "1" -- "*" PickupRequest : includes
Article "*" -- "0..1" DistributionCenter : dropped off at
Article "*" -- "0..1" FoodBank : dropped off at
DistributionCenter "1" -- "*" Article : examines
Client "0..1" -- "*" Delivery : receives
Delivery "1" -- "1" VolunteerDriver : performed by
Delivery "1" -- "1" Article : delivers
Client "0..1" -- "1" H2SLocation : served by

@enduml

